//! Rebuild the editor's self-contained starter models.
//!
//! Run with `cargo run --locked --offline -p runtime --example generate_primitive_glbs`.
//! Add `-- --check` to compare the generated bytes with the committed assets.

use engine_core::PrimitiveKind;
use gltf::binary::{Glb, Header};
use runtime::assets::MeshData;
use serde_json::json;
use std::{borrow::Cow, error::Error, fs, io, path::Path};

fn main() -> Result<(), Box<dyn Error>> {
	let mut args = std::env::args_os().skip(1);
	let check = match (args.next(), args.next()) {
		(None, None) => false,
		(Some(flag), None) if flag == "--check" => true,
		_ => return Err("Usage: generate_primitive_glbs [--check]".into()),
	};
	let output = Path::new(env!("CARGO_MANIFEST_DIR"))
		.join("../../apps/editor-host/src-tauri/assets/primitives");
	if !check {
		fs::create_dir_all(&output)?;
	}
	for kind in PrimitiveKind::ALL {
		let destination = output.join(format!("{}.glb", kind.as_str()));
		let bytes = encode(kind)?;
		if check {
			if fs::read(&destination)? != bytes {
				return Err(
					format!("{} differs from the generated model", destination.display()).into(),
				);
			}
		} else {
			fs::write(destination, bytes)?;
		}
	}
	Ok(())
}

fn mesh(kind: PrimitiveKind) -> (MeshData, [f32; 3], [f32; 3]) {
	let (mesh, half_extents) = match kind {
		PrimitiveKind::Plane => (MeshData::plane(), [0.5, 0.0, 0.5]),
		PrimitiveKind::Cube => (MeshData::cube(), [0.5; 3]),
		PrimitiveKind::Sphere => (MeshData::sphere(), [0.5; 3]),
		PrimitiveKind::Capsule => (MeshData::capsule(), [0.5, 1.0, 0.5]),
	};
	(
		mesh,
		half_extents.map(|extent| if extent == 0.0 { 0.0 } else { -extent }),
		half_extents,
	)
}

// Round offline samples to suppress tiny platform math differences in the
// rounded models and emit one representation for both signs of zero.
fn canonical_sample(value: f32) -> f32 {
	let value = (value * 10_000.0).round() / 10_000.0;
	if value == 0.0 { 0.0 } else { value }
}

fn encode(kind: PrimitiveKind) -> Result<Vec<u8>, Box<dyn Error>> {
	const FLOAT: u32 = 5126;
	const UNSIGNED_INT: u32 = 5125;
	const ARRAY_BUFFER: u32 = 34962;
	const ELEMENT_ARRAY_BUFFER: u32 = 34963;
	const FLOAT_BYTES: usize = size_of::<f32>();
	const VERTEX_BYTES: usize = 8 * FLOAT_BYTES;

	let (mesh, expected_min, expected_max) = mesh(kind);
	let vertices = mesh.vertices();
	let indices = mesh.indices();
	let vertex_bytes = vertices.len() * VERTEX_BYTES;
	let mut bytes = Vec::with_capacity(vertex_bytes + size_of_val(indices));
	let mut min = [f32::INFINITY; 3];
	let mut max = [f32::NEG_INFINITY; 3];
	for vertex in vertices {
		let position = vertex.position.map(canonical_sample);
		for axis in 0..3 {
			min[axis] = min[axis].min(position[axis]);
			max[axis] = max[axis].max(position[axis]);
		}
		for value in position
			.into_iter()
			.chain(vertex.normal.map(canonical_sample))
			.chain(vertex.uv.map(canonical_sample))
		{
			if !value.is_finite() {
				return Err(
					io::Error::new(io::ErrorKind::InvalidData, "Invalid primitive vertex").into(),
				);
			}
			bytes.extend_from_slice(&value.to_le_bytes());
		}
	}
	if min != expected_min || max != expected_max {
		return Err(format!(
			"{} model bounds changed: {min:?} to {max:?}",
			kind.display_name()
		)
		.into());
	}
	for index in indices {
		bytes.extend_from_slice(&index.to_le_bytes());
	}
	let name = kind.display_name();
	let document = json!({
		"asset": {"version": "2.0", "generator": "Game Engine starter models"},
		"scene": 0,
		"scenes": [{"nodes": [0]}],
		"nodes": [{"name": name, "mesh": 0}],
		"meshes": [{"name": name, "primitives": [{
			"attributes": {"POSITION": 0, "NORMAL": 1, "TEXCOORD_0": 2},
			"indices": 3, "material": 0
		}]}],
		"materials": [{"name": "Neutral", "pbrMetallicRoughness": {
			"baseColorFactor": [0.7, 0.7, 0.7, 1.0], "metallicFactor": 0.0, "roughnessFactor": 0.8
		}}],
		"buffers": [{"byteLength": bytes.len()}],
		"bufferViews": [
			{"buffer": 0, "byteLength": vertex_bytes, "byteStride": VERTEX_BYTES, "target": ARRAY_BUFFER},
			{"buffer": 0, "byteOffset": vertex_bytes, "byteLength": size_of_val(indices), "target": ELEMENT_ARRAY_BUFFER}
		],
		"accessors": [
			{"bufferView": 0, "componentType": FLOAT, "count": vertices.len(), "type": "VEC3", "min": min, "max": max},
			{"bufferView": 0, "byteOffset": 3 * FLOAT_BYTES, "componentType": FLOAT, "count": vertices.len(), "type": "VEC3"},
			{"bufferView": 0, "byteOffset": 6 * FLOAT_BYTES, "componentType": FLOAT, "count": vertices.len(), "type": "VEC2"},
			{"bufferView": 1, "componentType": UNSIGNED_INT, "count": indices.len(), "type": "SCALAR"}
		]
	});
	let json = serde_json::to_vec(&document)?;
	let length = u32::try_from(12 + 8 + json.len().next_multiple_of(4) + 8 + bytes.len())?;
	Ok(Glb {
		header: Header {
			magic: *b"glTF",
			version: 2,
			length,
		},
		json: Cow::Owned(json),
		bin: Some(Cow::Owned(bytes)),
	}
	.to_vec()?)
}
